import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

src = r'''
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <cuda_fp16.h>

template <typename scalar_t>
__global__ void argmax_kernel(const scalar_t* __restrict__ input,
                              scalar_t* __restrict__ output,
                              const int64_t* __restrict__ shape,
                              const int64_t* __restrict__ stride,
                              const int dim,
                              const int64_t reduction_size,
                              const int64_t total_output) {
    int64_t idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx >= total_output) return;

    // Determine the number of dimensions
    const int ndim = 3; // fixed for this model (batch, dim1, dim2)

    // Compute multi‑dimensional coordinates for the output (skip dim)
    int64_t residual = idx;
    int64_t coord[3];
    for (int d = ndim - 1; d >= 0; --d) {
        if (d == dim) {
            coord[d] = 0;
            continue;
        }
        coord[d] = residual % shape[d];
        residual /= shape[d];
    }

    // Compute the base offset (where reduction dimension index = 0)
    int64_t base_offset = 0;
    for (int d = 0; d < ndim; ++d) {
        base_offset += coord[d] * stride[d];
    }

    // Reduce over the chosen dimension
    float best_val = -FLT_MAX;
    int64_t best_idx = 0;
    for (int64_t k = 0; k < reduction_size; ++k) {
        int64_t offset = base_offset + k * stride[dim];
        float cur = __half2float(input[offset]);
        if (cur > best_val) {
            best_val = cur;
            best_idx = k;
        }
    }

    // Write the index as fp16 (as required by the task)
    output[idx] = __float2half(static_cast<float>(best_idx));
}

void launch_argmax_kernel(const at::Half* input,
                          at::Half* output,
                          const int64_t* shape,
                          const int64_t* stride,
                          const int dim,
                          const int64_t reduction_size,
                          const int64_t total_output,
                          cudaStream_t stream) {
    const int threads = 256;
    const int blocks = (total_output + threads - 1) / threads;
    argmax_kernel<at::Half><<<blocks, threads, 0, stream>>>(
        input,
        output,
        shape,
        stride,
        dim,
        reduction_size,
        total_output);
}
'''

module = load_inline(name='argmax_cuda',
                     cpp_sources='',
                     cuda_sources=src,
                     functions=['launch_argmax_kernel'],
                     verbose=False)

class ArgmaxFunction(torch.autograd.Function):
    @staticmethod
    def forward(ctx, input: torch.Tensor, dim: int):
        assert input.is_cuda and input.dtype == torch.float16
        ndim = input.dim()
        shape = torch.tensor(list(input.shape), dtype=torch.int64, device='cuda')
        stride = torch.tensor(list(input.stride()), dtype=torch.int64, device='cuda')
        reduction_size = input.shape[dim]

        out_shape = list(input.shape)
        del out_shape[dim]
        output = torch.empty(out_shape, dtype=torch.float16, device='cuda')

        total_output = output.numel()
        stream = torch.cuda.current_stream().cuda_stream

        module.launch_argmax_kernel(
            input.data_ptr(),
            output.data_ptr(),
            shape.data_ptr(),
            stride.data_ptr(),
            dim,
            reduction_size,
            total_output,
            stream
        )
        return output

    @staticmethod
    def backward(ctx, *grad_outputs):
        # argmax is non‑differentiable; return None for gradients
        return None, None

class ModelNew(nn.Module):
    def __init__(self, dim: int):
        super().__init__()
        self.dim = dim

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return ArgmaxFunction.apply(x, self.dim)

# Example usage (mirrors the reference API)
if __name__ == "__main__":
    batch_size = 128
    dim1 = 4096
    dim2 = 4095

    def get_inputs():
        x = torch.rand(batch_size, dim1, dim2, dtype=torch.float16, device='cuda')
        return [x]

    def get_init_inputs():
        return [1]

    model = ModelNew(dim=2).cuda()
    x = get_inputs()[0]
    out = model(x)
    print(out.shape, out.dtype)
